import plistlib

messages_file = "/Users/radoniusz/Library/Developer/CoreSimulator/Devices/53CBD69C-E05C-4DAC-9A2C-2504C42CB57F/data/Containers/Shared/AppGroup/58B41E47-2302-430E-B165-30206FF0042C/MXFileStore/@alice:localhost/rooms/!iXzQwfCBtArPYzbVbw:localhost/messages"

with open(messages_file, 'rb') as f:
    data = plistlib.load(f)

objects = data.get('$objects', [])

def resolve_uid(uid_obj):
    """Resolve a UID to its object"""
    if hasattr(uid_obj, 'integer'):
        return objects[uid_obj.integer] if uid_obj.integer < len(objects) else None
    return uid_obj

print("=== Book Club Room - All Messages ===\n")

messages = []
for obj in objects:
    if isinstance(obj, dict) and '$class' in obj:
        event_type = obj.get('eventType', None)
        # eventType 1 is usually m.room.message
        if event_type == 1:
            user_id_ref = obj.get('userId')
            content_ref = obj.get('content')
            timestamp = obj.get('originServerTs')

            user_id = resolve_uid(user_id_ref) if user_id_ref else 'Unknown'
            content = resolve_uid(content_ref) if content_ref else {}

            if isinstance(content, dict):
                body = content.get('body', '')
                if body:
                    messages.append({
                        'user': user_id,
                        'body': body,
                        'timestamp': timestamp
                    })

# Sort by timestamp
messages.sort(key=lambda x: x['timestamp'] if x['timestamp'] else 0)

# Display messages
for i, msg in enumerate(messages, 1):
    print(f"{i}. {msg['user']}")
    print(f"   {msg['body']}")
    print(f"   Timestamp: {msg['timestamp']}")
    print()

if not messages:
    print("No messages found. Let's look at all strings in the file:")
    print()
    for i, obj in enumerate(objects):
        if isinstance(obj, str) and len(obj) > 5:
            print(f"{i}: {obj}")
